def site_svg():
 s='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 860" role="img" aria-label="六栋分翼住宅与10格错列总图"><rect width="800" height="860" fill="#e7ecde"/><text x="28" y="30" font-size="18" fill="#415744">北 ↑ −Z　东 → +X</text><g transform="translate(22,48) scale(4.6)">'
 for x,z in load(R/'paths.json')['cells_xz']:s+=f'<rect x="{x}" y="{z}" width="1.1" height="1.1" fill="#d0bb94"/>'
 for t in PAR['towers']:
  pts=' '.join(f'{t["x"]+x},{t["z"]+z}' for x,z in t['outline']);color='#bf926d' if t['type']=='A' else '#8b7564'
  s+=f'<polygon points="{pts}" fill="{color}" stroke="#6d5039" stroke-width=".5"/><text x="{t["x"]+t["w"]/2}" y="{t["z"]+13}" text-anchor="middle" font-size="3.5" fill="#fff8e9">{t["id"]} · {t["storeys"]}F</text>'
 s+='<text x="62" y="79" font-size="4" fill="#47613c">中央共享花园</text><text x="44" y="163" font-size="3" fill="#47613c">主入口</text></g></svg>';return s

def building(v):
 body='<div class="tags">'+''.join('<span class="tag">'+t+'</span>' for t in ['V2 · 分翼体块','前排三房＋书房','后排一梯两户','120 户内饰','每栋后退 10 格'])+'</div>'
 body+='<div class="hero"><img src="'+pic(P/'se_day.png',1900)+'" alt="新版六栋住宅实体"><p>所有成品图与交互几何均回读自 '+RUN+' 最终 NBT；原版材质与照明的近似预览。</p></div>'
 body+='<div class="stats">'+''.join('<div><span class="stat">'+a+'</span><small>'+b+'</small></div>' for a,b in [('120','逐户布置'),('780','功能房间／区域'),('1,620','户内家具模块'),('41 / 120','住户亮灯；公共梯厅有灯')])+'</div>'
 body+=section('change','01','从矩形盒子，到有进退的住宅','<div class="grid">'+fig('se_day.png','上一版 V1_r06','原先的小前排、矩形整层与连续屋顶。',C/'review/previews/V1_r06')+fig('se_day.png','本版 V2_r05','前排扩宽；住宅翼、凹入核心和分段屋顶形成更明确的层次。')+'</div>'+table(['项目','前排 A1–A3','后排 B1–B3'],[['层数 / 每层户数','10 层 / 1 户','15 层 / 2 户'],['主楼外包尺寸','30 × 28 格（原23 × 25）','37 × 25 格，局部凹入'],['平面轮廓面积','722 格²，含墙与公共交通','822 格²，含墙与公共交通'],['户内用途','三卧室、书房、客厅、餐厅、厨房、家务区、两卫、更衣储物','每户两卧室、客餐厅、厨房、卫生间'],['外部层次','朝花园的深阳台＋主卧阳台','双翼阳台＋凹入的公共核心']])+'<p class="foot">轮廓面积用于方块体量比较，不等于现实住宅套内面积。P01 的色块按墙厚与通道细化，主要轮廓保持一致。</p>')
 body+=section('homes','02','内饰已经放进每一户','<div class="grid">'+fig('A_cut.png','前排标准层 · 三房＋书房','客餐厅连贯，卧室分翼；厨房、家务、两卫与储物独立组织。')+fig('B_cut.png','后排标准层 · 一梯两户','两户分别入户；卧室在外缘，客餐厅和阳台面向花园。')+fig('A_plan.png','前排最终方块平面','主楼轮廓按 P01 建造；核心稍向玄关延伸，留出两格通道。')+fig('B_plan.png','后排最终方块平面','家具绕开入户、厨房和阳台的连接位置。')+'</div><div class="grid" style="margin-top:22px">'+fig('living_detail.png','客餐厅近景','沙发、茶几、电视柜、餐桌椅、收纳和阳台形成可辨认的组合。')+fig('exploded.png','前排二层分解','原方块按竖向拉开：地板、房间、嵌灯吊顶、上层地板；仅为展示。',C/'review/previews'/(RUN+'_exploded'))+'</div><div class="note">120 户均有实际方块内饰。床形、厨卫设施和电梯目前是装饰／静态表达；没有声称可睡眠、可运行电梯或真实给排水。</div>')
 body+=section('interactive','03','逐栋、逐层查看','<p>选择“逐层内饰”，可切换 A1–B3 与各层；支持正俯视、旋转、缩放和日夜。首次加载需要解压完整几何。</p><button class="primary" id="load3d">打开交互模型</button><div id="threeD"></div>')
 body+=section('views','04','四面与夜景','<div class="controls"><label>方向 <select id="face"><option value="se">东南</option><option value="sw">西南</option><option value="ne">东北</option><option value="nw">西北</option></select></label><label><input type="checkbox" id="nightToggle"> 夜景</label></div><div class="hero"><img id="mainView" src="'+pic(P/'se_day.png')+'" alt="四面日夜切换"></div><div class="grid">'+fig('facade_detail.png','窗、窗网与阳台层次','有突出笼式防盗网、薄网和无网窗；玻璃和封阳台按住户变化。')+fig('A_cut_night.png','切层夜景','灯位在吊顶内；仅部分住户亮灯，公共楼梯和梯厅保持照明。')+'</div><p class="foot">夜景是近似灯光计算；原版冷暖材质不代表彩色光传播，游戏实际亮度仍需导入核验。</p>')
 body+=section('garden','05','两排之间的共享花园','<div class="grid"><div>'+site_svg()+'</div>'+fig('garden_day.png','园林与入口连接','保留观水、活动、廊架和树荫节点；补接六栋新入口，检查步道完整宽度。')+'</div><div class="grid" style="margin-top:22px">'+fig('entry_detail.png','前排门厅与入口')+fig('top_day.png','垂直正交总俯视','两排逐栋向北退10格；横向间距50格。')+'</div>')
 body+=section('delivery','06','模型与检查','<p>最终 '+f'{MAN["non_air_blocks"]:,}'+' 个非空气方块；导出后独立读回一致。21项本案例几何与通行检查通过。</p>'+dl(R/'building.nbt','下载 NBT')+dl(R/'params_used.json','下载参数')+dl(R/'validation.json','查看检查原文')+'<details><summary>导入条件与版本</summary><p>Java Structure NBT，DataVersion 3955；160 × 86 × 166 格，稀疏、不写空气。需要支持大尺寸 NBT 的导入方式，并在空场地试用。放置原点加高度不得超过目标世界上界。尚未做 Minecraft 实机导入、碰撞和灯光测试。</p><pre>SHA256 '+MAN['sha256']+'</pre></details>')
 views={q+'_'+m:pic(P/(q+'_'+m+'.png')) for q in ['se','sw','ne','nw'] for m in ['day','night']}
 script='const VIEWS='+json.dumps(views)+';const VIEWER='+json.dumps(v)+';function swap(){document.getElementById("mainView").src=VIEWS[document.getElementById("face").value+"_"+(document.getElementById("nightToggle").checked?"night":"day")]}document.getElementById("face").addEventListener("change",swap);document.getElementById("nightToggle").addEventListener("change",swap);document.getElementById("load3d").addEventListener("click",function(){const f=document.createElement("iframe");f.title="千禧年住宅交互模型";f.srcdoc=VIEWER;document.getElementById("threeD").append(f);this.remove()});'
 return shell('千禧年住宅 · 分翼与内饰','从批准的平面出发，把前排的大户型、后排的双户住宅和共同花园一起落成方块。',[('change','变化'),('homes','内饰'),('interactive','逐层查看'),('views','日夜'),('garden','园林'),('delivery','下载')],body,script)

def process():
 body='<div class="dark"><h2>从批准的平面，到最终 NBT。</h2><p>本轮按“来制作，包括内饰”实施 P01。原版 V1 的负例、五轮 V2 输出和实际失败记录保留；没有新增网络研究或用生成图替代成品。</p></div>'
 body+=section('input','01','输入与采用范围','<div class="grid">'+fig('approved_P01.png','本轮批准的平面对比图','前排扩大分翼，后排双翼凹核心；色块作为功能意图，非施工墙线。',C/'input')+fig('style_photo.jpg','用户提供的千禧年风格照片','保留暖黄墙、红顶、银灰框、部分防盗网、空调和住户加装感。',C/'input')+'</div><p>此前生成参考图仍保存在 input/approved_reference.png，属于原创意向，不是测绘依据。本轮直接承接已有图与参数，没有新网址或新下载图片。原始 V1_r06 NBT 与 P01 JSON 哈希写在各轮 provenance.json。</p>')
 body+=section('contract','02','空间设定怎样落实',table(['意图','实际实现','检查边界'],[['六栋、前三后三','A：10层1户；B：15层2户；120户','首层也保留住户和独立公共入口'],['前排更大、更长','外包30×28格；轮廓722格²；西侧起居、中间核心、东侧卧室','轮廓按P01；室内墙线为方块深化'],['后排两户','外包37×25格；轮廓822格²；左右独立入户','局部凹口形成双翼'],['核心深化','前排楼梯向西占用1格，向南利用玄关附近空间；紧凑7×9楼梯加独立静态电梯','保留轮廓，未照抄概念图的楼梯图标'],['竖向构造','层高5格；3格室内净高＋下层吊顶灯光＋上层地板','楼梯洞口连续，保留69段楼层间连接'],['错列','A起点15/118、65/108、115/98；B为10/31、60/21、110/11','每排逐栋X+50、Z−10']]))
 body+=section('shape','03','体块、立面与屋顶','<div class="grid">'+fig('ne_day.png','最终背向整体','窄楼梯窗、住宅翼与分开的屋顶轮廓。')+fig('front_elevation.png','最终南向立面','前后两排的高度和面宽差异。')+'</div><p>21个分段屋顶构件覆盖六栋主体；阳台是有楼板、围栏和门洞的实体空间。窗网按稳定住户／窗组ID选择：突出式193组、薄网126组、无网521组（含120组公共窗）。没有逐方块独立随机染色。</p>')
 body+=section('interior','04','内饰从功能到方块',table(['区域','布置内容','实际范围'],[['前排大户型','客厅、餐厅、厨房、家务、书房、3卧室、2卫、更衣储物','30户；每户11个功能区域'],['后排两户','每户2卧室、客餐厅、厨房、卫生间','90户；每户5个功能区域'],['家具','床形、衣柜、桌椅、沙发、茶几、电视柜、书架、厨卫与洗衣模块','1,620组在最终NBT中逐一核对存活'],['公共交通','双跑楼梯、平台、梯厅、入口及部分信箱／长凳','75个楼层平台连接120户'],['HAF交接','6份schema 0.4交接输入→compile_handoff→案例家具消费者','编译器检查范围/冲突；具体家具由build_v2.py放置']])+'<p>所有房间入口与家具邻侧可走到。房间数量、家具数量和通行通过，不等于居住功能已经实现；实际床、电梯、给排水与门禁系统未实现。</p>')
 body+=section('lighting','05','照明与园林','<div class="grid">'+fig('se_night.png','整组夜景')+fig('garden_day.png','共享园林')+'</div><p>328个实际发光方块，41/120户亮灯；公共楼梯和梯厅有灯。现代住宅的灯放在下层吊顶位置，未在完整吊顶下额外挂整灯块。花园沿用已建水景、活动、廊架和树荫节点，新入口接入4,212个通路单元，检查完整步道宽度。</p>')
 body+=section('iterations','06','本轮实际迭代',table(['版本','结果','处理'],[['V1_r06','用户指出太方正、前排体量不足','保留原模型和对照图'],['P01','用户批准制作的平面对比','作为主楼轮廓与功能分配输入'],['V2_r01','120户内饰已生成；后排90户厨房被沙发挡住','独立回读定位入口附近家具；保留失败报告'],['V2_r02','厨房通路修正；补公共窄窗；原19项通过','扩大检查到阳台后，发现前排主卧阳台被更衣柜挡住'],['V2_r03','更衣柜移到另一侧，20项检查通过','随后检查场地与扩大的A3外缘'],['V2_r04','先移开A3旁一株树；树根专项检查发现另外两株与新体块重叠','保留树根失败报告'],['V2_r05','三株受影响树整体移位；21项检查通过','当前交付；用户审美和Minecraft实机检查待验']])+'<p>V2_r02 的扩展检查另存 review/V2_r02_expanded_validation.json，未覆写它原有的19项报告。旧错误不能用后来的通过结果抹去。</p>')
 body+=section('checks','07','最终回读检查',table(['检查','结果'],[[r['id'],r['status']] for r in VAL['checks']])+'<p>上述是最终NBT的方块占用、承托和两格净空检查。150个阳台、780个房间入口、120户入口和69段双跑楼梯均覆盖到；不声称完成真实游戏寻路、楼梯碰撞或原版光照测试。</p>'+dl(R/'validation.json','完整检查与范围')+dl(R/'manifest.json','最终文件信息'))
 body+=section('views','08','图像与查看器来自哪里','<div class="grid">'+fig('top_day.png','最终正交俯视')+fig('exploded.png','同源分层爆炸','最终A1二层的原方块只作竖向平移；映射与派生NBT另存。',C/'review/previews'/(RUN+'_exploded'))+'</div><p>四个等尺度45°日景、四个同机位夜景、正交俯视、四向立面、户型、入口与内饰近景，均读取最终NBT。离线铁栅栏用细杆近似原版透明纹理；渲染器增加局部范围裁剪，避免邻栋混进户型图。图像不是Minecraft游戏截图。</p>')
 files=['params_used.json','provenance.json','design_handoffs.json','resolved_plans.json','interiors.json','module_consumption.json','windows.json','lamps.json','stairs.json','paths.json']
 body+=section('files','09','可复跑的工程与文件',table(['文件','用途'],[['Estate.html','成果、内饰、逐层交互与模型下载'],['Estate_Process.html','本次流程、原始输入、实际错误与验证'],['Estate.nbt','最终Java结构NBT'],['Estate.zip','V1历史＋V2五轮＋批准P01＋源码＋最终预览']])+'<p>'+''.join(dl(R/f) for f in files)+'</p><pre>python -m pip install numpy Pillow fonttools\npython tools/agent.py --case millennium_estate --run replay\npython cases/millennium_estate/src/validate_v2.py --run replay\npython cases/millennium_estate/src/render_case.py --run replay\npython cases/millennium_estate/src/render_exploded.py --run replay\nESTATE_RUN=replay python cases/millennium_estate/src/build_reports_v2.py</pre><details><summary>查看本轮建筑适配器源码</summary><pre>'+esc((C/'src/build_v2.py').read_text())+'</pre></details>')
 body+=section('limits','10','当前能力与待验边界','<p>完成的是一个明确设计的原创住宅案例：由空间参数、局部规则和手工编写的案例消费者生成。没有自动图像分割、相机恢复、通用图像建模或模型权重训练。HAF主线仍是0.4，本次不修改个人skill版本。</p><p>尚待Minecraft实机核验：大尺寸NBT导入器、放置高度、半砖与楼梯碰撞、真实灯光。电梯静态，床形和家具装饰性。用户对最终比例、立面和内饰的审美确认保持开放。</p>')
 return shell('从平面到完整住宅','V2 制作记录：保留批准输入、实际迭代和可验证的输出。',[('input','输入'),('contract','空间'),('interior','内饰'),('iterations','迭代'),('checks','检查'),('files','工程')],body)

if __name__=='__main__':
 from fontTools import subset
 v=viewer();docs={'Estate.html':building(v),'Estate_Process.html':process()}
 f=subset.load_font(str(ROOT/'support/fonts/NotoSansCJKsc-Regular.otf'),subset.Options());ss=subset.Subsetter();ss.populate(text=''.join(docs.values())+v);ss.subset(f);f.flavor='woff';buf=io.BytesIO();f.save(buf);enc=base64.b64encode(buf.getvalue()).decode()
 v=re.sub(r'data:font/woff;base64,[A-Za-z0-9+/=]+',lambda m:'data:font/woff;base64,'+enc,v);(C/'review/viewer_v2.html').write_text(v);docs['Estate.html']=building(v)
 font='@font-face{font-family:Noto;src:url(data:font/woff;base64,'+enc+') format("woff");font-display:swap}'
 for name,s in docs.items():(OUT/name).write_text(s.replace('<style>','<style>'+font,1))
 shutil.copy2(R/'building.nbt',OUT/'Estate.nbt');print(json.dumps({p.name:p.stat().st_size for p in OUT.glob('Estate.*')}))
